/**
 * @param {number} n
 * @return {number}
 */
var maxProduct = function(n) {
    let max = 1;
    let res = 0;

    while (n > 0) {
        const rem = n % 10;
        res = Math.max(res, rem * max);
        max = Math.max(max, rem);
        n = Math.floor(n / 10);
    }

    return res;
};

